// destructiveStatements are run on a real server, so that the text the server writes to the
// binlog (backticks, a "generated by server" comment, the database qualifier) is what the DDL
// parser sees, not what a test author imagines it looks like.
var destructiveStatements = []struct {
	name, setup, statement string
}{
	{"drop table", "", "DROP TABLE binwave.victim"},
	{"drop table if exists", "", "DROP TABLE IF EXISTS binwave.victim"},
	{"truncate", "", "TRUNCATE TABLE binwave.victim"},
	{
		"drop partition",
		"CREATE TABLE binwave.victim (id INT NOT NULL, PRIMARY KEY (id)) PARTITION BY RANGE (id) (PARTITION p0 VALUES LESS THAN (100), PARTITION p1 VALUES LESS THAN (200))",
		"ALTER TABLE binwave.victim DROP PARTITION p0",
	},
	{
		"truncate partition",
		"CREATE TABLE binwave.victim (id INT NOT NULL, PRIMARY KEY (id)) PARTITION BY RANGE (id) (PARTITION p0 VALUES LESS THAN (100), PARTITION p1 VALUES LESS THAN (200))",
		"ALTER TABLE binwave.victim TRUNCATE PARTITION p0",
	},
}

// TestDropAndTruncateOfARealServerAreMirroredInFullMode: what the source does to its tables, the
// replica does: a dropped table is gone, a truncated one is empty, and replication goes on.
func TestDropAndTruncateOfARealServerAreMirroredInFullMode(t *testing.T) {
	t.Parallel()
	for _, tt := range destructiveStatements[:3] {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			my := testenv.StartMySQL(t)
			ch := testenv.StartClickHouse(t)
			mustExec(t, my, "CREATE TABLE binwave.victim (id INT PRIMARY KEY)", "CREATE TABLE binwave.other (id INT PRIMARY KEY)")
			cfg := engineConfig(t, my, ch, "file")
			cfg.DDL.Mode = config.DDLFull
			e := startHubEngine(t, cfg)
			mustExec(t, my, "INSERT INTO binwave.victim VALUES (1), (2)", "INSERT INTO binwave.other VALUES (1)")
			waitUntil(t, "the rows", 60*time.Second, func() bool { return chRowCount(t, ch, "victim") == 2 && chRowCount(t, ch, "other") == 1 })

			mustExec(t, my, tt.statement, "INSERT INTO binwave.other VALUES (2)")

			waitUntil(t, "the statement to be mirrored", 60*time.Second, func() bool {
				want := 0
				if strings.HasPrefix(tt.statement, "DROP") {
					want = -1 // the table does not exist any more
				}
				return chRowCount(t, ch, "victim") == want && chRowCount(t, ch, "other") == 2
			})
			e.stillRunning(t)
			if got := e.quarantinedTables(); len(got) != 0 {
				t.Errorf("quarantined %v", got)
			}
		})
	}
}

// TestDropAndTruncateAreNotAppliedInAdditiveMode: additive never removes anything, and says so.
func TestDropAndTruncateAreNotAppliedInAdditiveMode(t *testing.T) {
	t.Parallel()
	my := testenv.StartMySQL(t)
	ch := testenv.StartClickHouse(t)
	mustExec(t, my, "CREATE TABLE binwave.acct (id INT PRIMARY KEY, owner VARCHAR(20) NOT NULL, qty INT NOT NULL)")
	cfg := engineConfig(t, my, ch, "file")
	cfg.DDL.Mode = config.DDLAdditive

	e := startEngine(t, cfg)
	mustExec(t, my, "INSERT INTO binwave.acct VALUES (1, 'a', 1), (2, 'b', 2)")
	waitForConvergence(t, my, ch)

	mustExec(t, my, "TRUNCATE TABLE binwave.acct", "INSERT INTO binwave.acct VALUES (3, 'c', 3)")

	// ClickHouse keeps the rows the source truncated, and replication goes on.
	waitUntil(t, "the row inserted after the TRUNCATE", 60*time.Second, func() bool {
		got, ok := clickhouseAccounts(t, ch)
		_, has3 := got[3]
		return ok && has3
	})
	got, _ := clickhouseAccounts(t, ch)
	if len(got) != 3 {
		t.Errorf("ClickHouse holds %v, want the two rows of before the TRUNCATE and the new one", got)
	}
	select {
	case err := <-e.done:
		t.Fatalf("the engine stopped: %v", err)
	default:
	}
	if err := e.stop(t); err != nil {
		t.Errorf("stop returned %v", err)
	}
}

// TestPartitionStatementsOfARealServerAreSkippedWithAWarning: the rows stay in ClickHouse, the
// statement is counted, and replication goes on (mirroring partition statements is not supported yet).
func TestPartitionStatementsOfARealServerAreSkippedWithAWarning(t *testing.T) {
	t.Parallel()
	for _, tt := range destructiveStatements[3:] {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			my := testenv.StartMySQL(t)
			ch := testenv.StartClickHouse(t)
			mustExec(t, my, tt.setup, "CREATE TABLE binwave.other (id INT PRIMARY KEY)")
			cfg := engineConfig(t, my, ch, "file")
			e := startHubEngine(t, cfg)
			mustExec(t, my, "INSERT INTO binwave.victim VALUES (1), (150)")
			waitUntil(t, "the rows", 60*time.Second, func() bool { return chRowCount(t, ch, "victim") == 2 })

			mustExec(t, my, tt.statement, "INSERT INTO binwave.other VALUES (1)")

			waitUntil(t, "replication to go on", 60*time.Second, func() bool { return chRowCount(t, ch, "other") == 1 })
			if chRowCount(t, ch, "victim") != 2 {
				t.Error("rows were removed although partition operations are not applied")
			}
			e.stillRunning(t)
		})
	}
}

// TestDropDatabaseOfARealServerDropsTheReplicatedTables: the tables of the dropped database that
// binwave wrote are dropped in ClickHouse, the others stay, a table of binwave's shape there included.
func TestDropDatabaseOfARealServerDropsTheReplicatedTables(t *testing.T) {
	t.Parallel()
	my := testenv.StartMySQL(t)
	ch := testenv.StartClickHouse(t)
	createSourceDatabase(t, my, "other")
	mustExec(t, my, "CREATE TABLE other.t (id INT PRIMARY KEY)", "CREATE TABLE binwave.keep (id INT PRIMARY KEY)")
	cfg := engineConfigWith(t, my, ch, "file", `tables: {include: ["binwave.*", "other.*"]}`)
	cfg.Tables.TargetDatabase = "" // other.t is other.t in ClickHouse, where a table of someone else can be
	cfg.DDL.Mode = config.DDLFull
	e := startHubEngine(t, cfg)
	mustExec(t, my, "INSERT INTO other.t VALUES (1)", "INSERT INTO binwave.keep VALUES (1)")
	waitUntil(t, "the rows", 60*time.Second, func() bool { return chCount(t, ch, "other.t") == 1 && chCount(t, ch, "binwave.keep") == 1 })
	execCH(t, ch, "CREATE TABLE other.stray AS other.t")

	mustExec(t, my, "DROP DATABASE other", "INSERT INTO binwave.keep VALUES (2)")

	waitUntil(t, "the tables of the dropped database to go", 60*time.Second, func() bool {
		return chCount(t, ch, "other.t") == -1 && chCount(t, ch, "binwave.keep") == 2
	})
	if !chExists(t, ch, "other", "stray") {
		t.Error("DROP DATABASE dropped a table binwave never wrote to")
	}
	e.stillRunning(t)
}

// TestAPositionOfAPreReleaseIsRefused: a position saved by a pre-release that kept no list of tables
// stops the start with the configuration code, before anything is read: which ClickHouse tables it
// wrote cannot be told, and a DROP DATABASE replayed later would leave them or take another's.
func TestAPositionOfAPreReleaseIsRefused(t *testing.T) {
	t.Parallel()
	my := testenv.StartMySQL(t)
	ch := testenv.StartClickHouse(t)
	createSourceDatabase(t, my, "other")
	mustExec(t, my, "CREATE TABLE other.t (id INT PRIMARY KEY)")
	cfg := engineConfigWith(t, my, ch, "file", `tables: {include: ["other.t"]}`)
	cfg.Tables.TargetDatabase = ""
	cfg.DDL.Mode = config.DDLFull
	e := startEngine(t, cfg)
	mustExec(t, my, "INSERT INTO other.t VALUES (1)")
	waitUntil(t, "the rows", 60*time.Second, func() bool { return chCount(t, ch, "other.t") == 1 })
	if err := e.stop(t); err != nil {
		t.Fatal(err)
	}

	// The state a pre-release saved: the position, no list of tables.
	data, err := os.ReadFile(cfg.Checkpoint.FilePath)
	if err != nil {
		t.Fatal(err)
	}
	var doc map[string]any
	if err := json.Unmarshal(data, &doc); err != nil {
		t.Fatal(err)
	}
	if _, ok := doc["tables"]; !ok {
		t.Fatalf("the saved state %s has no list of tables to remove", data)
	}
	delete(doc, "tables")
	if data, err = json.Marshal(doc); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(cfg.Checkpoint.FilePath, data, 0o600); err != nil {
		t.Fatal(err)
	}
	mustExec(t, my, "INSERT INTO other.t VALUES (2)")

	ready, running, err := runUntilItEnds(t, cfg, 60*time.Second)
	if ready || running {
		t.Errorf("ready %v, running %v: the start must be refused", ready, running)
	}
	requireConfigError(t, err, "pre-release")
	if n := chCount(t, ch, "other.t"); n != 1 {
		t.Errorf("other.t has %d rows, want the 1 written before: nothing is read", n)
	}
	if saved, err := os.ReadFile(cfg.Checkpoint.FilePath); err != nil || string(saved) != string(data) {
		t.Errorf("the saved state changed: %s (%v)", saved, err)
	}
}

// createSourceDatabase creates a database in MySQL that the binwave user may read and write.
func createSourceDatabase(t *testing.T, my *testenv.MySQL, name string) {
	t.Helper()
	for _, q := range []string{"CREATE DATABASE " + name, "GRANT ALL ON " + name + ".* TO 'binwave'@'%'"} {
		if _, err := rootDB(t, my).Exec(q); err != nil {
			t.Fatal(q, err)
		}
	}
}

// chExists reports whether ClickHouse has the table.
func chExists(t *testing.T, ch *testenv.ClickHouse, database, table string) bool {
	t.Helper()
	var n uint64
	if err := ch.DB.QueryRow("SELECT count() FROM system.tables WHERE database = ? AND name = ?", database, table).Scan(&n); err != nil {
		t.Fatal(err)
	}
	return n == 1
}

// chCount counts the live rows of a ClickHouse table, database.table; -1 when it does not exist.
func chCount(t *testing.T, ch *testenv.ClickHouse, table string) int {
	t.Helper()
	var n uint64
	if err := ch.DB.QueryRow("SELECT count() FROM (SELECT * FROM " + table + " FINAL WHERE _is_deleted = 0)").Scan(&n); err != nil {
		return -1
	}
	return int(n)
}

// TestCreateTableSelectReplicatesItsRows: with row-based logging the server writes CREATE TABLE ...
// SELECT as one transaction, the statement and the rows it copied; both reach ClickHouse, and the
// stream goes on after it.
func TestCreateTableSelectReplicatesItsRows(t *testing.T) {
	t.Parallel()
	my := testenv.StartMySQL(t)
	ch := testenv.StartClickHouse(t)
	mustExec(t, my,
		"CREATE TABLE binwave.acct (id INT PRIMARY KEY, owner VARCHAR(20) NOT NULL, qty INT NOT NULL)",
		"INSERT INTO binwave.acct VALUES (1, 'a', 1), (2, 'b', 2)")
	e := startEngine(t, engineConfig(t, my, ch, "clickhouse"))

	mustExec(t, my, "CREATE TABLE binwave.copy (PRIMARY KEY (id)) SELECT * FROM binwave.acct", "INSERT INTO binwave.acct VALUES (3, 'c', 3)")
	waitUntil(t, "the copied rows", 60*time.Second, func() bool { return chRowCount(t, ch, "copy") == 2 })
	waitUntil(t, "the row after it", 60*time.Second, func() bool { return chRowCount(t, ch, "acct") == 1 }) // the engine started at the current position
	if err := e.stop(t); err != nil {
		t.Errorf("graceful stop returned %v", err)
	}
}
